mapper.select:
SELECT sw.id, sw.chain_id, sw.tx_hash, sw.log_index, sw.block_number, sw.block_timestamp * 1000 AS timestamp_ms, sw.direction, sw.dex, sw.aggregator, sw.token_in, tin.symbol AS token_in_symbol, tin.decimals AS token_in_decimals, sw.amount_in, sw.token_out, tout.symbol AS token_out_symbol, tout.decimals AS token_out_decimals, sw.amount_out, sw.confirm_status, sw.watched_address FROM swap sw LEFT JOIN token tin ON tin.chain_id = sw.chain_id AND tin.address = sw.token_in LEFT JOIN token tout ON tout.chain_id = sw.chain_id AND tout.address = sw.token_out WHERE sw.chain_id = #{query.chainId}
AND sw.watched_address = #{query.address}
AND sw.dex = #{query.dex}
AND sw.direction = #{query.direction}
ORDER BY sw.block_number DESC, sw.log_index DESC

SELECT chain_id, tx_hash, log_index, block_number, confirm_status, watched_address
FROM swap
WHERE chain_id = #{chainId}
  AND block_number <= #{head}
  AND confirm_status IN ('CONFIRMING', 'CONFIRMED')

mapper.update:
UPDATE swap
SET confirm_status = #{status}, updated_by = #{actor}, updated_at = NOW()
WHERE chain_id = #{chainId} AND tx_hash = #{txHash} AND log_index = #{logIndex}

UPDATE swap
SET confirm_status = #{status}, updated_by = #{actor}, updated_at = NOW()
WHERE chain_id = #{chainId}
  AND block_number > #{ancestor}
  AND confirm_status <> #{status}
